function getDateFromInput(hari, minggu, tahun = parseInt($('Tarikh Sekarang').first().json.tahun)) {
  const days = ["ahad", "isnin", "selasa", "rabu", "khamis", "jumaat", "sabtu"];

  // bulan semasa
  let bulan = parseInt($('Tarikh Sekarang').first().json.bulan);//new Date().getMonth() + 1;

  // mula dari hari pertama bulan semasa
  let date = new Date(tahun, bulan - 1, 1);
  let targetDayIndex = days.indexOf(hari.toLowerCase());

  if (targetDayIndex === -1) {
    throw new Error("Hari tidak sah");
  }

  let count = 0;
  let resultDate = null;

  // loop cari hari ke-n (minggu)
  while (date.getMonth() === bulan - 1) {
    if (date.getDay() === targetDayIndex) {
      count++;
      if (count === minggu) {
        resultDate = new Date(date);
        break;
      }
    }
    date.setDate(date.getDate() + 1);
  }

  if (!resultDate) {
    throw new Error("Gabungan hari/minggu tak wujud bulan ni");
  }

  // format YYYY-MM-DD
  let y = resultDate.getFullYear();
  let m = String(resultDate.getMonth() + 1).padStart(2, "0");
  let d = String(resultDate.getDate()).padStart(2, "0");

  return `${y}-${m}-${d}`;
}

